                inputs: JSON.stringify({
                    issue: '', leg: leg, reason: reason || '', pr: String(prNumber)
                })
            });
        },

        silentUpdateBranch: function (prNumber, silentToken, restoreToken) {
            return _ghSilentUpdateBranch(full, prNumber, silentToken, restoreToken);
        }
    };
}

