        snapshot: function (kinds) { return _ghSnapshot(owner, repo, kinds); },

        listMachineIssues: function (machineLabels, agentHandle, limit) {
            return _ghListMachineIssues(owner, repo, full, machineLabels, agentHandle, limit);
        },

