function _mutexMaxOf(q) {
    // gh-837 (merge cadence): q.mutexMax (default 1) — how many arms the
    // mutex admits CONCURRENTLY when the validationConcurrency knob is up.
    return (typeof q.mutexMax === 'number' && isFinite(q.mutexMax))
