    // slot count reaches mutexMax holders within mutexAmong.
    if (holders.length >= mutexMax) {
        console.log('   🔒 mutex "' + q.mutex + '" slots ' + holders.length + '/' + mutexMax +
            ' taken — rule defers (' + (mutexMax > 1 ? 'parallel window' : 'serial FIFO') + ')');
        return null;
    }
    return items;
}

